// mmdc parses in headless Chromium, so it needs no DOM shim; the in-process
// mermaid import below fails on valid input with "purify.addHook is not a
// function" because DOMPurify has no window in Node.
function mmdcParserValidation(content) {
  const mmdc = resolve(DEPS_DIR, "node_modules/.bin/mmdc");
  if (!existsSync(mmdc)) return { available: false };
  const dir = mkdtempSync(join(tmpdir(), "mermaid-validate-"));
  const input = join(dir, "input.mmd");
  const output = join(dir, "output.svg");
  writeFileSync(input, content);
  const args = ["-i", input, "-o", output, "-q"];
  const puppeteerConfig = resolve(DEPS_DIR, "puppeteer-config.json");
  if (existsSync(puppeteerConfig)) args.push("-p", puppeteerConfig);
  try {
    execFileSync(mmdc, args, { stdio: "pipe", timeout: 60000 });
    return { available: true, valid: true };
  } catch (e) {
    // mmdc prints the mermaid parse error on stderr; keep the first lines
    const stderr = (e.stderr?.toString() || e.message || String(e)).trim();
    const lines = stderr.split("\n").filter((l) => l.trim());
    const trace = lines.findIndex((l) => /^\s*(at |\S+\.parseError)/.test(l));
    const message = (trace > 0 ? lines.slice(0, trace) : lines.slice(0, 6)).join("\n  ");
    return { available: true, valid: false, error: message };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

